algorithms.pseudocode:
Input: generators {T_g}, initial state psi0, max_depth D
Output: ranks[0..D], stabilization depth N

states = [psi0]
for d = 0 to D:
    if d > 0:
        for each word w of length d:
            states.append(T_w * psi0)
    ranks[d] = numerical_rank(stack(states))
    if d > 0 and ranks[d] == ranks[d-1]:
        N = d - 1
        return ranks, N
return ranks, D
